import JsonService from"./Service/JsonService.js";import TemplateService from"./Service/TemplateService.js";import ProxyService from"./Service/ProxyService.js";import EntityDTO from"./DTO/EntityDTO.js";import OptionDTO from"./DTO/OptionDTO.js";import ResizeObserverService from"./Service/ResizeObserverService.js";export default class DyJsForm{constructor(selector="#dyjsform",{rawOutput:rawOutput=false,debugMode:debugMode=false}={}){this._options={debugMode:debugMode,selector:selector};this._entity=[];this._rawOutput=rawOutput;this._jsonService=new JsonService(this._rawOutput);this._templateService=new TemplateService(this._options);this._selector=selector;this._errors=[];this._resizeObserverService=new ResizeObserverService(this._options);return new ProxyService(this,this._options)}get entity(){return JSON.parse(JSON.stringify(this._entity))}getEntityData(){return JSON.parse(JSON.stringify(this._entity.filter((item=>!item.name.startsWith("dyjsform_action_")))))}set entity(array){this._entity=array.map((data=>{const options=(data.options||[]).map((opt=>new OptionDTO({name:opt.name||"",value:opt.value||"",maxCount:opt.maxCount||null})));return new EntityDTO({htmlElement:data.htmlElement||"",type:data.type||"",name:data.name||"",label:data.label||"",value:data.value||"",content:data.content||"",className:data.className||"",attr:data.attr||"",maxCount:data.maxCount||"",options:options,error:data.error||""})}));return this}get selector(){return this._selector}set selector(value){this._selector=value}init(json=""){const jsonHtml=document.querySelector(this._selector).getAttribute("data-input");const jsonData=json!==""?JSON.parse(json):jsonHtml!==""?JSON.parse(jsonHtml):null;this._templateService.loadTemplate().then((()=>{this._templateService.renderForm(this._selector).injectCSS();this.initHandlers();if(jsonData){this._jsonService.addRow(this.entity).loadOutputJson(jsonData);this.refreshForm()}}));return this}refreshForm(){this._templateService.renderForm(this._selector).renderRow(this._selector,this.entity,this._jsonService.json);this._jsonService.writeOutputJson(this._selector);this.initHandlers();return this}initHandlers(){this.initEventListeners();this.handleInputKeyup()}initEventListeners(){this.addHandler();this.deleteHandler();return this}addHandler(){document.querySelectorAll(".dyjsform_action_add").forEach((element=>{element.addEventListener("click",(event=>{event.preventDefault();this._jsonService.addRow(this.entity);this.refreshForm()}))}))}deleteHandler(){document.querySelectorAll(".dyjsform_action_remove").forEach((element=>{element.addEventListener("click",(event=>{const rowNumber=event.target.getAttribute("data-row");event.preventDefault();this._jsonService.removeRow(rowNumber);this.refreshForm()}))}))}onDataEdit(element){let rowNumber=parseInt(element.getAttribute("data-row"));let fieldName=element.getAttribute("data-name");let value=element.value;let jsonUpdated=this._jsonService.updateJsonByField(rowNumber,fieldName,value);if(!jsonUpdated.success){this._errors=jsonUpdated.errors;this.refreshForm()}else if(this._errors.length>0){this._errors=[];this.refreshForm()}this._jsonService.writeOutputJson(this._selector)}async handleInputKeyup(){for(const entity of this.getEntityData()){const elements=document.querySelectorAll("."+entity.name);if(elements.length>0){elements.forEach((element=>{element.addEventListener("keyup",(event=>{this.onDataEdit(event.target)}));element.addEventListener("change",(event=>{this.onDataEdit(event.target)}))}))}}return this}}